import { after } from 'next/server'

async function logPageView(page: string) {
  // Simulate analytics service call
  console.log(`[Analytics] Page view logged: ${page} at ${new Date().toISOString()}`)
  // In a real app, this would be an API call to your analytics service:
  // await fetch('https://analytics.example.com/track', {
  //   method: 'POST',
  //   body: JSON.stringify({ page, timestamp: Date.now() })
  // })
}

export default function Home() {
  // Schedule analytics logging after the response is sent
  // This does NOT block the response from being sent to the user
  after(() => {
    logPageView('/home')
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>This page logs analytics without blocking the response!</p>
    </main>
  )
}

